CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Administrator','Employee')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), must_change_password INTEGER NOT NULL DEFAULT 0 CHECK(must_change_password IN (0,1)), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires BIGINT NOT NULL, id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, last_seen TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE TABLE quote_sequences (year TEXT PRIMARY KEY, value INTEGER NOT NULL);
        CREATE TABLE workspace (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, settings TEXT NOT NULL, settings_version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
        CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, active INTEGER NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL, position INTEGER NOT NULL, updated_at TEXT NOT NULL);
        CREATE TABLE products (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL, code TEXT NOT NULL, active INTEGER NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL, position INTEGER NOT NULL, updated_at TEXT NOT NULL);
        CREATE TABLE customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, mobile TEXT NOT NULL, email TEXT NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL, position INTEGER NOT NULL, updated_at TEXT NOT NULL);
        CREATE TABLE quotations (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES customers(id), date TEXT NOT NULL, valid_until TEXT NOT NULL, status TEXT NOT NULL, salesperson TEXT NOT NULL, total BIGINT NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL, position INTEGER NOT NULL, updated_at TEXT NOT NULL);
        CREATE TABLE quotation_items (quotation_id TEXT NOT NULL REFERENCES quotations(id) ON DELETE CASCADE, id TEXT NOT NULL, product_id TEXT NOT NULL, quantity INTEGER NOT NULL, subtotal BIGINT NOT NULL, body TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(quotation_id,id));
        CREATE TABLE quotation_history (quotation_id TEXT NOT NULL REFERENCES quotations(id) ON DELETE CASCADE, position INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(quotation_id,position));
        CREATE TABLE audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, at TEXT NOT NULL, actor_id TEXT, actor_name TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL);
        CREATE TABLE auth_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires BIGINT NOT NULL);
        CREATE INDEX products_category ON products(category_id,active);
        CREATE INDEX products_name ON products(lower(name));
        CREATE INDEX customers_name ON customers(lower(name));
        CREATE INDEX customers_mobile ON customers(mobile);
        CREATE INDEX customers_email ON customers(email);
        CREATE INDEX quotations_date ON quotations(date);
        CREATE INDEX quotations_status_date ON quotations(status,date);
        CREATE INDEX quotations_customer ON quotations(customer_id,date);
        CREATE INDEX quotations_sales ON quotations(salesperson,date);
        CREATE INDEX audit_entity ON audit_events(entity_type,entity_id,id);
        CREATE INDEX audit_time ON audit_events(at);
